const STAGES = ["shadow", "drafts", "normal"] as const;
type Stage = (typeof STAGES)[number];

// what each stage lets a finished run do
const onFinish = {
  shadow: "save the diff and the proof to S3 for the weekly report; open nothing",
  drafts: "open a draft PR and ping only the owner",
  normal: "mark a clean PR ready and request the reviewer of the day",
};

// the stage a run uses: the lower of the charter and the override flag
export const effectiveStage = (charter: Stage, override?: Stage): Stage =>
  override && STAGES.indexOf(override) < STAGES.indexOf(charter) ? override : charter;

export const missingForPromotion = (s: RoutineStats, bench: SliceScore): string[] => {
  const missing: string[] = [];
  if (bench.solvedRate < 0.5) missing.push(`bench slice solved ${pct(bench.solvedRate)}, needs 50%`);
  if (s.kind === "bug-fixer" && bench.reproduceRate < 0.6) {
    missing.push(`reproduced ${pct(bench.reproduceRate)} of bugs, needs 60%`);
  }
  if (s.falseHeals || bench.falseHeals) missing.push("has false heals");
  if (s.runsAtStage < 10) missing.push(`only ${s.runsAtStage} runs at this stage`);
  return missing;
};

export const demotionReason = (s: RoutineStats): string | undefined => {
  if (s.falseHealsSinceStageChange) return "a false heal";
  if (s.revertedPrsWithin14Days.length) return `#${s.revertedPrsWithin14Days[0]} was reverted within 14 days`;
  if (s.mergeRate !== undefined && s.mergeRate < 0.5) return `only ${pct(s.mergeRate)} of its last 20 PRs merged`;
  return undefined;
};

export const evaluate = async (routine: Routine) => {
  const [s, bench] = await Promise.all([stats(routine), latestBench(routine)]);
  const at = STAGES.indexOf(routine.effectiveStage);
  const why = demotionReason(s);
  if (why && at > 0) {
    await flags.set(`routine:${routine.name}:stage_override`, STAGES[at - 1], { reason: why });
    await openCharterPr(routine, STAGES[at - 1], why);
    await slack.dm(routine.owner, `${routine.name} moved back to ${STAGES[at - 1]}: ${why}`);
  } else if (at < 2 && missingForPromotion(s, bench).length === 0) {
    await slack.dm(routine.owner, `${routine.name} qualifies for ${STAGES[at + 1]}. Open the charter PR if you agree.`);
  }
};

