export const STAGES = ["shadow", "drafts", "normal"] as const;
export type Stage = (typeof STAGES)[number];

export type Routine = {
  name: string;
  kind: string;
  stage: Stage;
  runsAtStage: number;
  falseHealsSinceStageChange: number;
  revertedWithin14Days: number[];
  mergeRate: number | null; // share of the last 20 closed PRs that merged; null with fewer than 20
  bench: { solved: number; reproduced: number | null; falseHeals: number };
};

const pct = (x: number) => `${Math.round(x * 100)}%`;

export const demotionReason = (r: Routine): string | undefined => {
  if (r.falseHealsSinceStageChange > 0) return "a false heal";
  if (r.revertedWithin14Days.length > 0) return `#${r.revertedWithin14Days[0]} was reverted within 14 days`;
  if (r.mergeRate !== null && r.mergeRate < 0.5) return `only ${pct(r.mergeRate)} of its last 20 PRs merged`;
  return undefined;
};

export const missingForPromotion = (r: Routine): string[] => {
  throw new Error("missingForPromotion is yours to write");
};

export const decide = (r: Routine): string => {
  const at = STAGES.indexOf(r.stage);
  const why = demotionReason(r);
  if (why && at > 0) return `${r.name}: ${r.stage} → ${STAGES[at - 1]} now (${why})`;
  if (at === STAGES.length - 1) return `${r.name}: stays ${r.stage}`;
  const missing = missingForPromotion(r);
  if (missing.length === 0) return `${r.name}: qualifies for ${STAGES[at + 1]}; DM the owner`;
  return `${r.name}: stays ${r.stage} (${missing.join("; ")})`;
};
EOF

