  const missing: string[] = [];
  if (r.bench.solved < 0.5) missing.push(`bench solved ${pct(r.bench.solved)}, needs 50%`);
  if (r.kind === "bug-fixer" && (r.bench.reproduced ?? 0) < 0.6) {
    missing.push(`reproduced ${pct(r.bench.reproduced ?? 0)} of bugs, needs 60%`);
  }
  if (r.bench.falseHeals > 0 || r.falseHealsSinceStageChange > 0) missing.push("has false heals");
  if (r.runsAtStage < 10) missing.push(`only ${r.runsAtStage} runs at this stage, needs 10`);
  return missing;
};
